import{_ as a,o,c as t,al as i}from"./chunks/framework.7vp1BMOE.js";const p=JSON.parse('{"title":"ROS 2","description":"","frontmatter":{},"headers":[],"relativePath":"uk/ros2/index.md","filePath":"uk/ros2/index.md"}'),r={name:"uk/ros2/index.md"};function n(s,e,l,d,c,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="ros-2" tabindex="-1">ROS 2 <a class="header-anchor" href="#ros-2" aria-label="Permalink to &quot;ROS 2&quot;">​</a></h1><p><a href="https://docs.ros.org/en/humble/#" target="_blank" rel="noreferrer">ROS 2</a> is a powerful general purpose robotics library that can be used with the PX4 Autopilot to create powerful drone applications.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Tip The PX4 development team highly recommend that you use/migrate to this version of ROS!</p><p>This is the newest version of <a href="https://www.ros.org/" target="_blank" rel="noreferrer">ROS</a> (Robot Operating System). It significantly improves on ROS &quot;1&quot;, and in particular allows a much deeper and lower-latency integration with PX4.</p></div><p>ROS користується активною екосистемою розробників, які вирішують загальні проблеми робототехніки, а також має доступ до інших бібліотек програмного забезпечення, написаних для Linux. It can be used, for example, for <a href="./../computer_vision/">computer vision</a> solutions.</p><p>ROS 2 enables a very deep integration with PX4, to the extent that you can create flight modes in ROS 2 that are indistinguisable from internal PX4 modes, and directly read from and write to internal uORB topics at high rate. It is recommended (in particular) for control and communication from a companion computer where low latency is important, when leveraging existing libraries from Linux, or when writing new high level flight modes.</p><p>Communication between ROS 2 and PX4 can leverage two independent middlewares:</p><ul><li><a href="./../middleware/uxrce_dds">XRCE-DDS protocol</a> — Original middleware. More tested and included by default in most PX4 builds.</li><li><a href="./../middleware/zenoh">Zenoh protocol</a> — Must be manually added and enabled to most PX4 builds.</li></ul><p>The middlewares expose PX4 <a href="./../msg_docs/">uORB messages</a> as ROS 2 messages and types, effectively allowing direct access to PX4 from ROS 2 workflows and nodes. The middlewares use uORB message definitions to generate code to serialise and deserialise the messages heading in and out of PX4. Ці ж визначення повідомлень використовуються в програмах ROS 2, щоб дозволити інтерпретувати повідомлення.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>ROS 2 can also connect with PX4 using <a href="https://github.com/mavlink/mavros/tree/ros2/mavros" target="_blank" rel="noreferrer">MAVROS</a> instead of XRCE-DDS / Zenoh. This option is supported by the MAVROS project (it is not documented here).</p></div><p>To use the <a href="./../ros2/user_guide">ROS 2</a> over XRCE-DDS / Zenoh effectively, you must (at time of writing) have a reasonable understanding of the PX4 internal architecture and conventions, which differ from those used by ROS. У найближчому майбутньому ми плануємо надати ROS 2 API до абстрактних конвенцій PX4, разом із прикладами, що демонструють їх використання.</p><h2 id="topics" tabindex="-1">Topics <a class="header-anchor" href="#topics" aria-label="Permalink to &quot;Topics&quot;">​</a></h2><p>Основні теми в цьому розділі є:</p><ul><li><a href="./../ros2/user_guide">ROS 2 User Guide</a>: A PX4-centric overview of ROS 2, covering installation, setup, and how to build ROS 2 applications that communicate with PX4.</li><li><a href="./../ros2/offboard_control">ROS 2 Offboard Control Example</a>: A C++ tutorial examples showing how to do position control in <a href="./../flight_modes/offboard">offboard mode</a> from a ROS 2 node.</li><li><a href="./../ros2/multi_vehicle">ROS 2 Multi Vehicle Simulation</a>: Instructions for connecting to multiple PX4 simulations via single ROS 2 agent.</li><li><a href="./../ros2/px4_ros2_interface_lib">PX4 ROS 2 Interface Library</a>: A C++ library that simplifies interacting with PX4 from ROS 2. Can be used to create and register flight modes written using ROS 2 and send position estimates from ROS 2 applications such as a VIO system.</li><li><a href="./../ros2/px4_ros2_msg_translation_node">ROS 2 Message Translation Node</a>: A ROS 2 message translation node that enables communication between PX4 and ROS 2 applications that were compiled with different sets of messages versions.</li></ul><h2 id="подальша-інформація" tabindex="-1">Подальша інформація <a class="header-anchor" href="#подальша-інформація" aria-label="Permalink to &quot;Подальша інформація&quot;">​</a></h2><ul><li><a href="./../middleware/uxrce_dds">XRCE-DDS (PX4-ROS 2/DDS Bridge)</a>: PX4 middleware leveranging micro XRCE-DDS for connecting to ROS 2.</li><li><a href="./../middleware/zenoh">Zenoh (PX4 ROS 2)</a>: PX4 middleware leveraging Zenoh pico for connecting to ROS 2.</li></ul>',15)])])}const u=a(r,[["render",n]]);export{p as __pageData,u as default};
